grant usage,select on sequence public.agent_usage_ledger_id_seq to authenticated;

create or replace function public.reserve_agent_budget(p_metric text,p_quantity numeric,p_run_id text default null,p_actor text default 'unknown',p_provider text default null,p_model text default null,p_metadata jsonb default '{}'::jsonb) returns jsonb language plpgsql security invoker set search_path=public,private,pg_temp as $$ declare pol public.agent_budget_policies%rowtype; used_day numeric; used_month numeric; reservation_id bigint; begin if not private.is_admin() and current_user<>'service_role' then raise exception 'not_authorized'; end if; if p_quantity is null or p_quantity<=0 then raise exception 'quantity_must_be_positive'; end if; perform pg_advisory_xact_lock(hashtext('agent-budget:'||p_metric)); select * into pol from public.agent_budget_policies where metric=p_metric and enabled=true; if not found then raise exception 'budget_metric_not_enabled:%',p_metric; end if; select coalesce(sum(quantity),0) into used_day from public.agent_usage_ledger where metric=p_metric and status in ('reserved','committed') and created_at>=date_trunc('day',now()); select coalesce(sum(quantity),0) into used_month from public.agent_usage_ledger where metric=p_metric and status in ('reserved','committed') and created_at>=date_trunc('month',now()); if used_day+p_quantity>pol.daily_limit then return jsonb_build_object('allowed',false,'reason','daily_limit','used',used_day,'limit',pol.daily_limit); end if; if pol.monthly_limit is not null and used_month+p_quantity>pol.monthly_limit then return jsonb_build_object('allowed',false,'reason','monthly_limit','used',used_month,'limit',pol.monthly_limit); end if; insert into public.agent_usage_ledger(run_id,actor,provider,model,metric,quantity,status,metadata) values(p_run_id,coalesce(p_actor,'unknown'),p_provider,p_model,p_metric,p_quantity,'reserved',coalesce(p_metadata,'{}'::jsonb)) returning id into reservation_id; return jsonb_build_object('allowed',true,'reservation_id',reservation_id,'used_day_before',used_day,'daily_limit',pol.daily_limit,'soft',used_day+p_quantity>=pol.daily_limit*pol.soft_threshold); end $$;

create or replace function public.finalize_agent_budget(p_reservation_id bigint,p_actual_quantity numeric,p_metadata jsonb default '{}'::jsonb) returns boolean language plpgsql security invoker set search_path=public,private,pg_temp as $$ begin if not private.is_admin() and current_user<>'service_role' then raise exception 'not_authorized'; end if; update public.agent_usage_ledger set quantity=greatest(coalesce(p_actual_quantity,0),0),status='committed',metadata=metadata||coalesce(p_metadata,'{}'::jsonb) where id=p_reservation_id and status='reserved'; return found; end $$;

create or replace function public.release_agent_budget(p_reservation_id bigint) returns boolean language plpgsql security invoker set search_path=public,private,pg_temp as $$ begin if not private.is_admin() and current_user<>'service_role' then raise exception 'not_authorized'; end if; update public.agent_usage_ledger set status='released' where id=p_reservation_id and status='reserved'; return found; end $$;
